import React, { useState, useEffect, Suspense } from "react";
import { useLocation, useHistory, Route, Switch } from "react-router-dom";
import axios from "axios";
import { Canvas } from "@react-three/fiber";
import { OrbitControls, Html } from "@react-three/drei";
import AdminNavbar from "components/Navbars/AdminNavbar";
import Footer from "components/Footer/Footer";
import Sidebar from "components/Sidebar/Sidebar";
import FixedPlugin from "components/FixedPlugin/FixedPlugin.js";
import { Card, Button, Alert, Badge } from "react-bootstrap";
import { StallCustomizationProvider } from "contexts/StallCustomizationContext";
import GoldStall from "components/StallCustomization/GoldStall";
import PlatinumStall from "components/StallCustomization/PlatinumStall";
import DiamondStall from "components/StallCustomization/DiamondStall";
import routes from "routes.js";
import sidebarImage from "assets/img/sidebar-3.jpg";

const authHeaders = () => ({
  headers: { Authorization: localStorage.getItem("jwt") || "" },
});

// Demo stalls so the hall is never empty (used when the API has none yet).
const DEMO_STALLS = [
  { stallId: "demo-diamond", stallName: "Diamond Pavilion", stallType: "Diamond", tier: "Diamond", exhibitorEmail: "exhibitor@example.com" },
  { stallId: "demo-gold", stallName: "Gold Pavilion", stallType: "Gold", tier: "Gold", exhibitorEmail: "exhibitor@example.com" },
  { stallId: "demo-platinum", stallName: "Platinum Pavilion", stallType: "Platinum", tier: "Platinum", exhibitorEmail: "exhibitor@example.com" },
];

function StallModel({ stallType }) {
  const type = (stallType || "Gold").toLowerCase();
  if (type === "platinum") return <PlatinumStall scale={[0.11, 0.11, 0.11]} />;
  if (type === "diamond") return <DiamondStall scale={[1.2, 1.2, 1.2]} />;
  return <GoldStall scale={[1.6, 1.6, 1.6]} />;
}

function ExhibitionHall({ stalls, selectedId, onSelect }) {
  const spread = (i, n) => (i - (n - 1) / 2) * 10;
  return (
    <>
      <color attach="background" args={["#0b1020"]} />
      <OrbitControls target={[0, 2, 0]} maxPolarAngle={Math.PI / 2 - 0.05} />
      <ambientLight intensity={0.7} />
      <directionalLight
        position={[10, 14, 8]}
        intensity={1.2}
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
      />
      {/* Hall floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[80, 40]} />
        <meshStandardMaterial color="#1a2340" />
      </mesh>
      {/* Center carpet */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.01, 4]}>
        <planeGeometry args={[70, 4]} />
        <meshStandardMaterial color="#7a1f2b" />
      </mesh>
      {stalls.map((stall, i) => {
        const x = spread(i, stalls.length);
        const selected = stall.stallId === selectedId;
        return (
          <group key={stall.stallId || i} position={[x, 0, -2]}>
            <Suspense fallback={null}>
              <StallModel stallType={stall.stallType || stall.tier} />
            </Suspense>
            <Html position={[0, 7, 0]} center distanceFactor={20}>
              <div
                onClick={() => onSelect(stall)}
                style={{
                  cursor: "pointer",
                  background: selected ? "#0d6efd" : "rgba(0,0,0,0.65)",
                  color: "#fff",
                  padding: "4px 12px",
                  borderRadius: "12px",
                  fontSize: "13px",
                  whiteSpace: "nowrap",
                  border: selected ? "2px solid #fff" : "1px solid #888",
                }}
              >
                {stall.stallName || stall.stallId} ({stall.stallType || stall.tier || "Standard"})
              </div>
            </Html>
            {selected && (
              <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.02, 0]}>
                <ringGeometry args={[3.2, 3.8, 40]} />
                <meshBasicMaterial color="#0d6efd" side={2} />
              </mesh>
            )}
          </group>
        );
      })}
    </>
  );
}

function VisitExhibition() {
  const location = useLocation();
  const history = useHistory();
  const mainPanel = React.useRef(null);
  const [image, setImage] = React.useState(sidebarImage);
  const [color, setColor] = React.useState("black");
  const [hasImage, setHasImage] = React.useState(true);
  const [exhibition, setExhibition] = useState(null);
  const [stalls, setStalls] = useState([]);
  const [selectedStall, setSelectedStall] = useState(null);
  const [loading, setLoading] = useState(true);

  const getRoutes = (routes) => {
    return routes.map((prop, key) => {
      if (prop.layout === "/admin") {
        return (
          <Route
            path={prop.layout + prop.path}
            render={(props) => <prop.component {...props} />}
            key={key}
          />
        );
      } else {
        return null;
      }
    });
  };

  useEffect(() => {
    const stateId = location.state && location.state.exhibitionId;
    if (stateId) localStorage.setItem("visitExhibitionId", stateId);
    const targetId = stateId || localStorage.getItem("visitExhibitionId") || "";

    const load = async () => {
      try {
        const exRes = await axios.get(
          "http://localhost:8080/api/exhibitions",
          authHeaders()
        );
        const list = exRes.data || [];
        const current =
          list.find((e) => e.id === targetId) ||
          list.find((e) => e.started) ||
          list[0] ||
          null;
        setExhibition(current);

        let stallList = [];
        try {
          const stRes = await axios.get(
            "http://localhost:8080/api/stalls",
            authHeaders()
          );
          const all = stRes.data || [];
          stallList = current
            ? all.filter((s) => s.exhibitionId === current.id)
            : all;
          if (stallList.length === 0) stallList = all;
        } catch (e) {
        }
        setStalls(stallList.length > 0 ? stallList : DEMO_STALLS);
      } catch (e) {
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  return (
    <>
      <div className="wrapper">
        <Sidebar color={color} image={hasImage ? image : ""} routes={routes} />
        <div className="main-panel" ref={mainPanel}>
          <AdminNavbar />
          <div className="container-fluid">
            <Switch>{getRoutes(routes)}</Switch>
            <Card className="mb-3">
              <Card.Body>
                <div className="d-flex justify-content-between align-items-center flex-wrap">
                  <div>
                    <h4 className="m-0">
                      {exhibition ? exhibition.exhibitionName : "Exhibition Hall"}
                    </h4>
                    <small className="text-muted">
                      {exhibition ? exhibition.description : ""}
                    </small>
                  </div>
                  <div>
                    {exhibition && (
                      <Badge bg={exhibition.started ? "success" : "warning"} className="mr-2">
                        {exhibition.started ? "Running / Live" : "Not started"}
                      </Badge>
                    )}
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => history.push("/admin/exhibitions")}
                    >
                      Back to Exhibitions
                    </Button>
                  </div>
                </div>
                <hr />
                <Alert variant="info" className="mb-0">
                  Drag to look around, scroll to zoom, right-drag to pan. Click a
                  stall label to select it.
                </Alert>
              </Card.Body>
            </Card>
            {loading ? (
              <div className="text-center py-4">Loading 3D hall...</div>
            ) : (
              <StallCustomizationProvider>
                <Canvas
                  shadows
                  camera={{ position: [0, 7, 18], fov: 50 }}
                  style={{ height: "65vh", borderRadius: "8px" }}
                >
                  <Suspense fallback={null}>
                    <ExhibitionHall
                      stalls={stalls}
                      selectedId={selectedStall && selectedStall.stallId}
                      onSelect={setSelectedStall}
                    />
                  </Suspense>
                </Canvas>
              </StallCustomizationProvider>
            )}
            {selectedStall && (
              <Card className="mt-3">
                <Card.Body>
                  <h5>{selectedStall.stallName || selectedStall.stallId}</h5>
                  <p className="mb-1">
                    <strong>Type:</strong> {selectedStall.stallType || selectedStall.tier || "Standard"}
                  </p>
                  <p className="mb-0">
                    <strong>Exhibitor:</strong> {selectedStall.exhibitorEmail || "—"}
                  </p>
                </Card.Body>
              </Card>
            )}
          </div>
          <Footer />
        </div>
      </div>
      <FixedPlugin
        hasImage={hasImage}
        setHasImage={() => setHasImage(!hasImage)}
        color={color}
        setColor={(color) => setColor(color)}
        image={image}
        setImage={(image) => setImage(image)}
      />
    </>
  );
}

export default VisitExhibition;
